function postErrorCommentToJira(ticketKey, stage, errorMessage) {
    try {
        const m = commentMarkup.forTicket(ticketKey);
        let comment = m.h(3, m.bold('Development Workflow Error')) + '\n\n';
        comment += m.bold('Stage:') + ' ' + stage + '\n';
