    console.error('❌ Pull Request creation failed — no PR exists for ' + ctx.ticketKey + ':', prResult.error);
    if (resumeDevelopmentAgent(params, ctx.ticketKey, ctx.customParams, 'development_pr_creation', prResult.error)) {
        return { resume: true };
