    console.log('\n══ ' + label + ' ══');
    if (rule.source && rule.source !== 'jira') {
        var qdesc = JSON.stringify(rule.query || {});
        console.log('   Query[' + rule.source + ']: ' + qdesc + (rule.limit ? ' (limit: ' + rule.limit + ')' : ''));
    } else {
        console.log('   JQL: ' + interpolatedJql + (rule.limit ? ' (limit: ' + rule.limit + ')' : ''));
    }

