function isMeaningfulStatusLine(line) {
    return !!line.trim() &&
           !/^(\?\?|A )\s+factory-kit(\/|$)/.test(line) &&
           !gitStaging.isRuntimeArtifactStatusLine(line) &&
           line.indexOf('Script started') === -1 &&
