 */
function shouldSkipForQuotaPark(ticket, rule, jobParams) {
    var label = parkLabelOf(jobParams);
    if (!label) return false;
    if (rule && rule.quotaParkProbe === true) return false;
    var labels = (ticket && ticket.labels) ||
