                    console.log('Switching partial work from ' + (currentBranch || '(unknown)') +
                        ' to development branch: ' + plan.branch);
                    cliTool({ command: 'git checkout -B ' + plan.branch });
                }
                pushPartialWork(cliTool, config, ticketKey, plan);
            }
