    // Summary
    console.log('\n═══════════════════════════════════════════');
    var status = _results_.failed === 0 ? '✅ PASS' : '❌ FAIL';
    console.log('  ' + status + '  —  ' + _results_.passed + ' passed, ' + _results_.failed + ' failed');
    if (_results_.errors.length > 0) {
