            if (!testCode || !testCode.trim()) {
                console.log('  ⚠️  File not found or empty');
                continue;
            }
            eval(testCode);
        } catch (e) {
            _results_.failed++;
            console.log('  ❌ Error in test file: ' + (e.message || e));
        }
    }

    // Summary
    console.log('\n═══════════════════════════════════════════');
    var status = _results_.failed === 0 ? '✅ PASS' : '❌ FAIL';
